"""Evidence evaluation for the calibration-limits study."""

import json


def _canonical_json(value):
    """Return a stable representation that preserves JSON value types."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def _superseded_sources(record):
    """Normalize scalar and list forms of the supersedes field."""
    supersedes = record.get("supersedes", [])
    if isinstance(supersedes, list):
        return supersedes
    return [supersedes]


def evaluate(request, evidence, policy):
    """Evaluate a request without modifying any input."""
    request_conditions = request.get("conditions", {})
    required = policy.get("required_conditions", [])
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue

        conditions = record.get("conditions", {})
        if not isinstance(conditions, dict):
            continue
        if any(
            name not in conditions
            or _canonical_json(conditions[name])
            != _canonical_json(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = {
        source
        for superseding_record in eligible
        for source in _superseded_sources(superseding_record)
        if source != superseding_record.get("source")
    }
    eligible = [record for record in eligible if record.get("source") not in superseded]

    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record["source"] for record in eligible)
    values = {}
    for record in eligible:
        value = record.get("value")
        values.setdefault(_canonical_json(value), value)

    if len(values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = next(iter(values.values()))
    return {
        "status": "unsupported" if value is False else "supported",
        "value": value,
        "sources": sources,
        "unknowns": [],
    }

